const item = $input.first().json;
const body = item.body;
const headers = item.headers ?? {};
const errors = [];

if (!body || typeof body !== 'object' || Array.isArray(body)) {
  errors.push('Body must be a JSON object.');
}

const serialized = JSON.stringify(body ?? null);
if (new TextEncoder().encode(serialized).byteLength > 1048576) {
  errors.push('Webhook body exceeds the 1 MiB transport limit.');
}

const request = body?.request;
const correlationId = body?.correlationId ?? headers['x-correlation-id'];
const tenderId = request?.tender?.tenderId;
const idempotencyKey = request?.tender?.idempotencyKey;
const printableIdentifier = (value) => typeof value === 'string' && value.trim().length > 0;

if (!printableIdentifier(correlationId) || correlationId.length > 128 || !/^[\x21-\x7e]+$/.test(correlationId)) {
  errors.push('correlationId must be 1-128 printable ASCII characters.');
}
if (!printableIdentifier(tenderId)) {
  errors.push('request.tender.tenderId is required.');
}
if (!printableIdentifier(idempotencyKey)) {
  errors.push('request.tender.idempotencyKey is required.');
}

if (errors.length > 0) {
  return [{ json: { ok: false, statusCode: 400, body: { error: 'TRANSPORT_VALIDATION_FAILED', correlationId: printableIdentifier(correlationId) ? correlationId : null, issues: errors } } }];
}

return [{ json: { ok: true, correlationId, tenderId, idempotencyKey, request } }];

const response = $input.first().json;
const correlationId = $('Normalize Transport').item.json.correlationId;
const statusCode = Number.isInteger(response.statusCode) ? response.statusCode : 502;
const body = response.body && typeof response.body === 'object'
  ? response.body
  : { error: 'TENDER_API_UNAVAILABLE', correlationId, detail: response.message ?? 'Tender API request failed.' };
return [{ json: { statusCode, body } }];

const prepared = $input.first().json;
const statusCode = prepared.statusCode;
const body = prepared.body && typeof prepared.body === 'object' ? prepared.body : {};
const correlationId = body.correlationId ?? $('Normalize Transport').item.json.correlationId;
const tenderId = body.tenderId ?? $('Normalize Transport').item.json.tenderId;
const runId = body.runId;
const base = { correlationId, tenderId, runId: runId ?? null, outboundMessagesSent: 0 };
let integrationOutcome;

if (statusCode < 200 || statusCode >= 300 || body.status === 'FAILED' || body.failure) {
  integrationOutcome = { ...base, type: 'TECHNICAL_ERROR', key: `technical-error:${runId ?? correlationId}`, failure: body.failure ?? body.error ?? 'TENDER_API_REQUEST_FAILED', businessRouteRetained: body.route ?? null };
} else if (!runId || !tenderId || !correlationId) {
  integrationOutcome = { ...base, type: 'TECHNICAL_ERROR', key: `technical-error:${runId ?? correlationId}`, failure: 'INVALID_TENDER_RESPONSE', businessRouteRetained: body.route ?? null };
} else if (body.status === 'PROCESSING' && !body.route) {
  integrationOutcome = { ...base, type: 'PENDING', key: `pending:${runId}`, reason: 'Tender processing has not produced a business route.' };
} else if (body.status === 'COMPLETED' && body.route === 'READY_FOR_PRICING') {
  integrationOutcome = { ...base, type: 'PRICING_HANDOFF_RECORDED', key: `pricing-handoff:${runId}`, pricingOwner: 'TENDER_API', handoffStatus: 'SUCCEEDED', handoffAttemptsInitiatedByWorkflow: 0 };
} else if (body.status === 'COMPLETED' && body.route === 'NEEDS_INFORMATION') {
  integrationOutcome = { ...base, type: 'INFORMATION_REQUEST_RECORDED', key: `information-request:${runId}`, synthetic: true, deliveryStatus: 'NOT_SENT', description: 'Synthetic information-request receipt; no email or external message was sent.' };
} else if (body.status === 'COMPLETED' && body.route === 'HUMAN_REVIEW') {
  integrationOutcome = { ...base, type: 'HUMAN_REVIEW_AVAILABLE', key: `human-review:${runId}`, consolePath: `/tenders/${runId}`, reviewTaskCreatedByWorkflow: false };
} else if (body.status === 'COMPLETED' && body.route === 'DUPLICATE') {
  integrationOutcome = { ...base, type: 'DUPLICATE_RECORDED', key: `duplicate:${runId}`, stopped: true };
} else {
  integrationOutcome = { ...base, type: 'TECHNICAL_ERROR', key: `technical-error:${runId ?? correlationId}`, failure: 'UNEXPECTED_TENDER_RESPONSE', businessRouteRetained: body.route ?? null };
}

const responseStatusCode = integrationOutcome.type === 'TECHNICAL_ERROR' && statusCode >= 200 && statusCode < 300 ? 502 : statusCode;
return [{ json: { statusCode: responseStatusCode, body: { ...body, integrationOutcome } } }];
